    /** ЗАСТОЙ ПО БЛИЖАЙШЕЙ ГРУППЕ (v132): «держит дистанцию» меряется до центра его БЛИЖАЙШЕЙ группы (вооружённые в ENGAGE_RANGE от
     *  его ближайшего к нам вооружённого), а не до центра всей армии. Матч с Coldkimchi 07.09 (6a9f0af1): его армия расколота —
     *  пятеро (4 стрелка, 1 мили, без лекаря) в углу (1–4,1–6), три лекаря и три мили в 25–40 клетках; центр всей армии уходил
     *  вместе с дальними, «keeps its distance (8 -> 12 over 8 ticks)» на 274-м отправил армию за флагами на 300 тиков в двух шагах
     *  от загнанной пятёрки, а гонка/отряд затем расколола нас самих; к 330-му он собрался и снёс нас по частям.
     *  ОТВЕРГНУТО регрессом стенда: против РОССЫПИ ближайшая группа — один-два крипа, которые не «держат дистанцию» так, как центр
     *  всей армии, застой не наступает, и армия гоняется вместо флагов — spread m19 21782:24309, m24 21763:24272, m29 18582:24318,
     *  farm m31 17356:23672, scatter m31 24035:24318 из побед в поражения по очкам (при этом семейства в обычной сетке: split +2,
     *  blitz 4-4 → 4-4, входы тождественны). Предмет угла остаётся: застой обязан отличать загнанную ГРУППУ от россыпи —
     *  например, по её собственной неподвижности и слабости в досягаемости, а не по дистанции до центра. */
    private const val USE_STALL_NEAREST_GROUP = false

    /** Враг «рядом» с армией (для отхода): в этих клетках от кого-то из наших; из отхода выходим, когда он
     *  дальше NEAR_RANGE + NEAR_RELEASE (иначе постура прыгала каждый тик на кромке радиуса). */
    private const val NEAR_RANGE = 14
    private const val NEAR_RELEASE = 6

    private const val COHESION_GAP = 8
    private const val COHESION_GAP_MAX = 100
    private const val ENGAGE_COHESION_TICKS = 2
    private const val POST_STANDOFF = 2
    private const val ENGAGE_RANGE = 8
    private const val CLOSE_STANDOFF = 2
    private const val APPROACH_WINDOW = 20
    /** ПРЕСЛЕДУЕМЫ ТОЛЬКО ТЕМ, КТО МОЖЕТ ДОЙТИ (проба после серии 407–426, матчи 407/421): см. hunted. Дальше HUNTED_FAR =
     *  EVADE_RANGE + APPROACH_WINDOW и без темпа сближения его сила не делает нас преследуемыми: пока окно темпа заметит поворот
     *  к нам, он пройдёт не больше окна и останется за EVADE_RANGE. ОТВЕРГНУТО стендом в трёх срезах на сценариях с армией без
     *  одного мили (OURWEAK=1 — форма матча 407; без неё проба на 26 + 8 + 22 сценариях не срабатывала ни разу): tour 5-3 → 6-2 во
     *  всех трёх срезах, но split 7-1 → 3-5 (центроид), → 4-4 (только при проигранной гонке, lostRaceNow), → 4-4 (ближайший его
     *  вооружённый вместо центроида): без «преследуемы» армия идёт за флагами в группы фермера, которого уклонением обыгрывала
     *  по очкам; на tour m28 (9246:17774 в третьем срезе) переключение hunted на границе сбрасывает состояние уклонения и даёт
     *  точку ухода там, где стационарное состояние её не находило. Предмет 407 остаётся: 530 тиков EVADE при его армии в 47
     *  клетках и досягаемом отставании. */
    private const val USE_HUNTED_NEEDS_REACH = false
    private const val HUNTED_FAR = EVADE_RANGE + APPROACH_WINDOW
    /** Запаздывание реакции на пошедшего врага: окно темпа плюс период пересчёта (см. exitMargin). */
    private const val REACTION_LAG = APPROACH_WINDOW + EVADE_EVAL_EVERY

